"""Released manifests are generic over call mode; pins are regenerated by a verb."""

import argparse
import json
import shutil
import sys

import pytest

from tau2.data_model.benchmark import TextBenchmarkConditions
from tau2.data_model.run_config import AudioNativeConfig
from tau2.data_model.simulation import TextRunConfig, VoiceRunConfig
from tau2.multilingual.runtime import load_language
from tau2.runner.cli import check_benchmark_selection, selected_benchmark
from tau2.runner.presets import (
    BenchmarkRequest,
    binding_revision,
    load_frame,
    resolve_benchmark,
    verify_frame,
)


def _population(frame):
    return [
        (cell.language, cell.domain, cell.canonical_task_ids) for cell in frame.cells
    ]


def test_text_manifest_mirrors_the_voice_population():
    text, voice = load_frame("text"), load_frame("voice")
    assert (text.mode, voice.mode) == ("text", "voice")
    assert len(text.cells) == 18
    assert _population(text) == _population(voice)
    assert {cell.language for cell in text.cells} == {
        "en",
        "es",
        "pt",
        "hi",
        "zh",
        "ko",
    }
    assert {cell.domain for cell in text.cells} == {"airline", "retail", "telecom"}
    # The call mode is part of each binding: the same pack binds differently.
    assert all(
        t.binding_revision != v.binding_revision
        for t, v in zip(text.cells, voice.cells)
    )


@pytest.mark.parametrize("name", ("voice", "text"))
def test_shipped_manifest_matches_current_packs(name):
    frame = load_frame(name)
    verify_frame(frame, name)
    for cell in frame.cells:
        assert cell.binding_revision == binding_revision(
            load_language(cell.language, cell.domain, mode=frame.mode)
        )


def test_text_benchmark_resolves_ordinary_text_configs(tmp_path):
    plan = resolve_benchmark(
        BenchmarkRequest(
            preset="text",
            template=TextRunConfig(workers=0),
            output=tmp_path / "text",
            languages=["es"],
            domains=["retail"],
        )
    )
    assert plan.partial and len(plan.frame.cells) == 18
    (config,) = plan.configs
    assert type(config) is TextRunConfig
    assert isinstance(config.benchmark.conditions, TextBenchmarkConditions)
    assert config.llm_user == "openai/gpt-5.5"
    assert config.llm_args_user == {"reasoning_effort": "low"}
    assert config.communicate_scoring.scorer == "semantic"
    assert len(config.task_ids) == 50
    assert (
        config.language_artifacts
        == load_language("es", "retail", mode="text").artifact_pins
    )


def test_manifest_mode_must_match_the_template(tmp_path):
    with pytest.raises(ValueError, match="runs text calls"):
        resolve_benchmark(
            BenchmarkRequest(
                preset="text",
                template=VoiceRunConfig(audio_native_config=AudioNativeConfig()),
                output=tmp_path / "a",
            )
        )
    with pytest.raises(ValueError, match="runs voice calls"):
        resolve_benchmark(
            BenchmarkRequest(
                preset="voice", template=TextRunConfig(workers=0), output=tmp_path / "b"
            )
        )


@pytest.mark.parametrize(
    ("benchmark", "audio_native", "expected"),
    (
        (None, True, "voice"),
        (None, False, None),
        ("text", False, "text"),
        ("none", True, None),
        ("none", False, None),
    ),
)
def test_voice_runs_default_to_the_voice_benchmark_text_runs_are_custom(
    benchmark, audio_native, expected
):
    args = argparse.Namespace(benchmark=benchmark, audio_native=audio_native)
    assert selected_benchmark(args) == expected


def test_cli_selection_rejects_a_mode_mismatch():
    args = argparse.Namespace(
        benchmark="text", audio_native=True, domain=None, language=None
    )
    with pytest.raises(ValueError, match="drop --audio-native"):
        check_benchmark_selection(args)
    args = argparse.Namespace(
        benchmark="voice", audio_native=False, domain=None, language=None
    )
    with pytest.raises(ValueError, match="add --audio-native"):
        check_benchmark_selection(args)


@pytest.fixture
def data_copy(tmp_path, monkeypatch):
    """A DATA_DIR whose manifests are writable copies and all else links to data."""
    import tau2.utils

    source = tau2.utils.DATA_DIR
    root = tmp_path / "data"
    root.mkdir()
    for child in source.iterdir():
        if child.name != "tau2":
            (root / child.name).symlink_to(child)
    (root / "tau2").mkdir()
    for child in (source / "tau2").iterdir():
        if child.name == "benchmarks":
            shutil.copytree(child, root / "tau2" / "benchmarks")
        else:
            (root / "tau2" / child.name).symlink_to(child)
    monkeypatch.setattr(tau2.utils, "DATA_DIR", root)
    return root / "tau2" / "benchmarks"


def _cli(monkeypatch, *argv):
    from tau2.cli import main

    monkeypatch.setattr(sys, "argv", ["tau2", *argv])
    main()


def test_pin_verb_is_idempotent_and_restores_drifted_pins(
    data_copy, monkeypatch, capsys
):
    shipped = (data_copy / "voice.json").read_text()
    _cli(monkeypatch, "benchmarks", "pin", "voice")
    assert (data_copy / "voice.json").read_text() == shipped
    capsys.readouterr()

    drifted = json.loads(shipped)
    drifted["task_subsets"]["retail"]["sha256"] = "0" * 64
    drifted["cells"][4]["binding_revision"] = "stale"
    (data_copy / "voice.json").write_text(json.dumps(drifted))
    # Changed pins are never written under the unchanged release revision.
    for same_revision in ((), ("--revision", drifted["revision"])):
        with pytest.raises(ValueError, match="pass --revision"):
            _cli(monkeypatch, "benchmarks", "pin", "voice", *same_revision)
        assert json.loads((data_copy / "voice.json").read_text()) == drifted
    _cli(monkeypatch, "benchmarks", "pin", "voice", "--revision", "next-release")
    restored = {**json.loads(shipped), "revision": "next-release"}
    assert json.loads((data_copy / "voice.json").read_text()) == restored
    assert json.loads(capsys.readouterr().out) == restored


@pytest.mark.parametrize("name", ["../escaped", "Voice", "a/b", ""])
def test_pin_from_rejects_unsafe_target_names(data_copy, monkeypatch, name):
    def listing():
        return sorted(
            p.name for d in (data_copy, data_copy.parent) for p in d.iterdir()
        )

    before = listing()
    with pytest.raises(ValueError, match="Invalid benchmark preset name"):
        _cli(
            monkeypatch,
            "benchmarks",
            "pin",
            name,
            "--from",
            "voice",
            "--mode",
            "text",
            "--revision",
            "r",
            "--benchmark-version",
            "v",
        )
    assert listing() == before
    assert not (data_copy.parent / "escaped.json").exists()


def test_pin_verb_derives_the_shipped_text_manifest(data_copy, monkeypatch):
    shipped = json.loads((data_copy / "text.json").read_text())
    (data_copy / "text.json").unlink()
    _cli(
        monkeypatch,
        "benchmarks",
        "pin",
        "text",
        "--from",
        "voice",
        "--mode",
        "text",
        "--revision",
        shipped["revision"],
        "--benchmark-version",
        shipped["benchmark_version"],
    )
    assert json.loads((data_copy / "text.json").read_text()) == shipped
    with pytest.raises(FileExistsError):
        _cli(
            monkeypatch,
            "benchmarks",
            "pin",
            "text",
            "--from",
            "voice",
            "--mode",
            "text",
            "--revision",
            "x",
            "--benchmark-version",
            "y",
        )


def test_benchmarks_list_reports_both_modes(monkeypatch, capsys):
    _cli(monkeypatch, "benchmarks", "list")
    rows = {row["name"]: row for row in json.loads(capsys.readouterr().out)}
    assert rows["voice"]["mode"] == "voice" and rows["text"]["mode"] == "text"
    assert rows["voice"]["cells"] == rows["text"]["cells"] == 18
